IPC_SUBCLASS_RE = re.compile(r"[A-HY][0-9]{2}[A-Z]")
YEAR_RE = re.compile(r"\b(19[0-9]{2}|20[0-9]{2})\b")


def read_table(path: Path, sheet_name: str | None = None) -> pd.DataFrame:
    suffix = path.suffix.lower()
    if suffix in {".xlsx", ".xls"}:
        return pd.read_excel(path, sheet_name=sheet_name or 0)
    if suffix == ".csv":
        return pd.read_csv(path, encoding="utf-8-sig")
    if suffix == ".txt":
        return pd.read_csv(path, sep="\t", encoding="utf-8-sig")
    raise ValueError(f"Unsupported input file type: {path.suffix}")


def parse_year(value: object) -> float:
    if pd.isna(value):
        return np.nan
    if isinstance(value, (int, float, np.integer, np.floating)):
        year = int(value)
        return float(year) if 1800 <= year <= 2100 else np.nan
    text = str(value)
    years = [int(match) for match in YEAR_RE.findall(text)]
    if not years:
        return np.nan
    return float(min(years))


def parse_ipc_subclasses(value: object) -> list[str]:
    if pd.isna(value):
        return []
    text = str(value).upper()
    text = (
        text.replace("\u2010", "-")
        .replace("\u2011", "-")
        .replace("\u2012", "-")
        .replace("\u2013", "-")
        .replace("\u2014", "-")
        .replace("\u2212", "-")
    )
    return IPC_SUBCLASS_RE.findall(text)


def subclasses_to_text(codes: list[str]) -> str:
    return "; ".join(sorted(set(codes)))


def safe_doc_id(row: pd.Series, index: int) -> str:
    for col in (
        "Family ID",
        "Representative Lens ID",
        "Lens ID",
        "Display Key",
        "Representative Display Key",
        "UT",
        "DOI",
        "ID",
        "PN",
    ):
        if col in row.index and pd.notna(row[col]) and str(row[col]).strip():
            return str(row[col]).split(";")[0].splitlines()[0].strip()
    return f"DOC_{index + 1:06d}"


def require_sklearn() -> None:
    if SKLEARN_IMPORT_ERROR is not None:
        raise ModuleNotFoundError(
            "This pipeline requires scikit-learn. Install it in the active Python environment "
            "before running PatentBERT topic scoring."
        ) from SKLEARN_IMPORT_ERROR


def compute_topic_embeddings(embeddings: np.ndarray, topic_ids: np.ndarray) -> tuple[pd.DataFrame, np.ndarray]:
    require_sklearn()
    topics = np.array(sorted(pd.Series(topic_ids).dropna().astype(int).unique()), dtype=int)
    doc_embeddings = normalize(np.asarray(embeddings, dtype=np.float64), norm="l2", axis=1)
    centroids = []
    for topic in topics:
        idx = np.where(topic_ids == topic)[0]
        centroids.append(doc_embeddings[idx].mean(axis=0))
    topic_matrix = normalize(np.vstack(centroids), norm="l2", axis=1)
    return pd.DataFrame({"topic_id": topics}), topic_matrix


def compute_representative_docs(
    docs: pd.DataFrame,
    embeddings: np.ndarray,
    topic_index: pd.DataFrame,
    topic_embeddings: np.ndarray,
    top_n: int = 5,
) -> pd.Series:
    require_sklearn()
    doc_embeddings = normalize(np.asarray(embeddings, dtype=np.float64), norm="l2", axis=1)
    titles = docs["TI_raw"].fillna("").astype(str).to_numpy()
    topic_ids = docs["topic_id"].astype(int).to_numpy()
    representatives: dict[int, str] = {}

    for pos, topic in enumerate(topic_index["topic_id"].astype(int).to_numpy()):
        idx = np.where(topic_ids == topic)[0]
        if len(idx) == 0:
            representatives[topic] = ""
            continue
        sims = doc_embeddings[idx] @ topic_embeddings[pos]
        selected = idx[np.argsort(-sims)[:top_n]]
        representatives[topic] = " || ".join(titles[i] for i in selected)
    return pd.Series(representatives)


def safe_text(value: object) -> str:
    if value is None:
        return ""
    try:
        if pd.isna(value):
            return ""
    except (TypeError, ValueError):
        pass
    return str(value)


def compact_text(value: object, max_chars: int = 800) -> str:
    text = normalize_space(safe_text(value))
    if len(text) <= max_chars:
        return text
    return text[: max_chars - 3].rstrip() + "..."


def nullable_int(value: object) -> int | None:
    try:
        if pd.isna(value):
            return None
    except (TypeError, ValueError):
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def nullable_float(value: object) -> float | None:
    try:
        if pd.isna(value):
            return None
    except (TypeError, ValueError):
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def load_deepseek_topic_cache(path: Path) -> dict[str, dict]:
    if not path.exists():
        return {}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return {}
    if not isinstance(payload, dict):
        return {}
    return {str(key): value for key, value in payload.items() if isinstance(value, dict)}


def save_deepseek_topic_cache(path: Path, cache: dict[str, dict]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(cache, ensure_ascii=False, indent=2), encoding="utf-8")


def deepseek_payload_signature(payload: dict) -> str:
    encoded = json.dumps(
        {
            "schema_version": DEEPSEEK_TOPIC_SCHEMA_VERSION,
            "payload": payload,
        },
        ensure_ascii=False,
        sort_keys=True,
    ).encode("utf-8")
    return hashlib.sha1(encoded).hexdigest()[:16]


def string_list(value: object) -> list[str]:
    if isinstance(value, list):
        return [normalize_space(str(item)) for item in value if normalize_space(str(item))]
    text = normalize_space(safe_text(value))
    return [text] if text else []


def deepseek_bool(value: object, default: bool = True) -> bool:
    if isinstance(value, bool):
        return value
    text = normalize_space(safe_text(value)).lower()
    if not text:
        return default
    if text in {"true", "yes", "y", "1", "relevant", "related", "相关", "是"}:
        return True
    if text in {"false", "no", "n", "0", "not_relevant", "unrelated", "irrelevant", "不相关", "否"}:
        return False
    return default


def normalize_fusion_relevance(result: dict) -> tuple[bool, str, str]:
    raw_relevance = normalize_space(safe_text(result.get("fusion_relevance", ""))).lower()
    is_related = deepseek_bool(result.get("is_fusion_related", None), default=True)
    if raw_relevance in {"not_relevant", "unrelated", "irrelevant", "不相关"}:
        is_related = False
        relevance = "not_relevant"
    elif raw_relevance in {"uncertain", "unknown", "不确定"}:
        is_related = True
        relevance = "uncertain"
    elif raw_relevance in {"outlier"}:
        is_related = True
        relevance = "outlier"
    else:
        relevance = "relevant" if is_related else "not_relevant"

    reason = normalize_space(safe_text(result.get("fusion_relevance_reason", "")))
    if not reason:
        reason = "DeepSeek 未提供明确相关性理由，按保守规则保留该主题。" if is_related else "DeepSeek 判定该主题与核聚变不相关。"
    return is_related, relevance, reason


