def build_topic_evidence_payload(
    docs: pd.DataFrame,
    topic: int,
    topic_doc_indices: np.ndarray,
    representative_indices: np.ndarray,
) -> dict:
    group = docs.iloc[topic_doc_indices]
    years = pd.to_numeric(group["year"], errors="coerce") if "year" in group.columns else pd.Series(dtype=float)
    ipc_counter: Counter[str] = Counter()
    if "ipc_subclasses" in group.columns:
        for value in group["ipc_subclasses"].fillna("").astype(str):
            ipc_counter.update(code.strip() for code in value.split(";") if code.strip())

    def top_values(column: str, limit: int = 8) -> list[dict]:
        if column not in group.columns:
            return []
        values = group[column].fillna("").astype(str).map(normalize_space)
        counts = Counter(value for value in values if value)
        return [{"label": label, "count": int(count)} for label, count in counts.most_common(limit)]

    evidence_docs = []
    for doc_idx in representative_indices:
        row = docs.iloc[int(doc_idx)]
        evidence_docs.append(
            {
                "doc_id": safe_text(row.get("doc_id", "")),
                "title": compact_text(row.get("TI_raw", ""), 260),
                "abstract": compact_text(row.get("AB_raw", ""), 900),
                "representation_text": compact_text(row.get("TI_repr_text", ""), 700),
                "year": nullable_int(row.get("year", None)),
                "ipc_subclasses": safe_text(row.get("ipc_subclasses", "")),
                "citation_count": nullable_float(row.get("citation_count", None)),
            }
        )

    return {
        "topic_id": int(topic),
        "topic_size": int(len(topic_doc_indices)),
        "year_min": nullable_int(years.min()) if not years.dropna().empty else None,
        "year_max": nullable_int(years.max()) if not years.dropna().empty else None,
        "top_ipc_subclasses": [code for code, _ in ipc_counter.most_common(12)],
        "top_technology_labels": top_values("source_technology_label"),
        "top_route_labels": top_values("source_route_label"),
        "top_chain_level1": top_values("source_chain_level1"),
        "top_chain_level2": top_values("source_chain_level2"),
        "top_chain_level3": top_values("source_chain_level3"),
        "representative_docs": evidence_docs,
    }


def local_topic_interpretation(topic_payload: dict) -> dict:
    """Build a deterministic static interpretation from IncoPat labels and evidence."""

    def labels(key: str, limit: int = 3) -> list[str]:
        return [
            normalize_space(safe_text(item.get("label", "")))
            for item in topic_payload.get(key, [])[:limit]
            if normalize_space(safe_text(item.get("label", "")))
        ]

    routes = labels("top_route_labels", 3)
    technologies = labels("top_technology_labels", 3)
    level1 = [value for value in labels("top_chain_level1", 3) if value != "不适用"]
    level2 = [value for value in labels("top_chain_level2", 3) if value != "不适用"]
    level3 = [value for value in labels("top_chain_level3", 4) if value != "不适用"]
    documents = topic_payload.get("representative_docs", [])
    titles = [normalize_space(safe_text(item.get("title", ""))) for item in documents]
    titles = [title for title in titles if title][:3]

    replacement = {"确认无核聚变应用映射": "无直接聚变应用映射", "确认无关": "无直接聚变应用映射"}
    routes = [replacement.get(value, value) for value in routes]
    technologies = [replacement.get(value, value) for value in technologies]
    focus = (level3 or routes or technologies or level2 or ["聚变相关技术"])[0]
    route_name = focus if focus.endswith(("技术", "系统", "装置", "材料", "应用")) else f"{focus}技术"
    route_name = route_name[:18]
    route_context = "、".join(routes[:2]) or "聚变相关工程路线"
    objects = "、".join(level3[:3] or technologies[:3] or routes[:3])
    chain_position = "、".join(level1) if level1 else "跨环节支撑"
    chain_detail = "、".join(level2[:2]) if level2 else "聚变相关装置、部件与应用"

    summary = f"该主题集中于{focus}，主要覆盖{objects or route_context}等技术对象，并沿{route_context}方向形成专利布局。"
    description = (
        f"该主题由 IncoPat 简单专利族的标题、摘要、IPC 与技术标签共同归纳，核心内容聚焦{focus}。"
        f"相关专利主要落在{chain_position}的{chain_detail}，具体边界以代表专利披露的技术对象为准。"
    )
    route_sentences = [f"围绕{item}开展结构、材料、工艺或系统方案布局。" for item in (level3[:4] or routes[:4])]
    if not route_sentences:
        route_sentences = [f"围绕{focus}形成从基础方案到工程应用的技术演进。"]
    evidence_sentences = [f"代表专利“{title}”体现了该主题的主要技术指向。" for title in titles]
    if not evidence_sentences:
        evidence_sentences = ["主题判断依据为聚类专利的标题、摘要、IPC 与 IncoPat 技术标签。"]
    scenarios = [f"可用于{item}相关的聚变工程研发与系统集成。" for item in (level3[:3] or level2[:3] or [focus])]
    return {
        "route_name_cn": route_name,
        "route_name_en": "IncoPat classified technology topic",
        "topic_summary": summary,
        "topic_description": description,
        "technology_route_sentences": route_sentences,
        "evidence_sentences": evidence_sentences,
        "fusion_industry_chain_position": chain_position,
        "fusion_industry_chain_relation": f"该技术通过{chain_detail}进入核聚变产业链，主要服务于{objects or focus}相关研发与工程活动。",
        "fusion_application_scenarios": scenarios,
        "is_fusion_related": True,
        "fusion_relevance": "relevant",
        "fusion_relevance_reason": "按已确认口径，全部 IncoPat 简单专利族均纳入聚变相关技术分析范围。",
        "confidence": "medium",
        "status": "generated_local",
        "model": "IncoPat标签规则与本地主题归纳",
        "generated_at": int(time.time()),
    }


