def parse_deepseek_json_content(content: str) -> dict:
    text = content.strip()
    if text.startswith("```"):
        text = re.sub(r"^```(?:json)?\s*", "", text, flags=re.IGNORECASE)
        text = re.sub(r"\s*```$", "", text).strip()
    try:
        result = json.loads(text)
    except json.JSONDecodeError as exc:
        excerpt = text[:1200]
        raise RuntimeError(
            "DeepSeek returned invalid JSON. This is usually a truncated or malformed model response. "
            f"JSON error: {exc}. Response excerpt: {excerpt!r}"
        ) from exc
    if not isinstance(result, dict):
        raise RuntimeError("DeepSeek returned a non-object JSON payload.")
    return result


def call_deepseek_topic_sentence(
    prompt: str,
    api_key: str,
    model: str,
    base_url: str,
    timeout: int,
    retries: int,
) -> dict:
    url = base_url.rstrip("/") + "/chat/completions"
    last_error: Exception | None = None
    for attempt in range(max(1, retries + 1)):
        retry_note = ""
        if attempt:
            retry_note = (
                "\n\n上一次请求失败或响应不是合法 JSON。请重新输出一个完整 JSON 对象，"
                "不要包含 Markdown，不要在字符串中使用未转义换行，不要省略任何结尾括号。"
            )
        body = {
            "model": model,
            "messages": [
                {
                    "role": "system",
                    "content": (
                        "你是核聚变专利主题提炼专家。必须输出有效 JSON；"
                        "主题表达必须是完整句子，不要输出孤立关键词列表。"
                    ),
                },
                {"role": "user", "content": prompt + retry_note},
            ],
            "response_format": {"type": "json_object"},
            "temperature": 0.05,
            "max_tokens": 2400,
        }
        request = urllib.request.Request(
            url=url,
            data=json.dumps(body, ensure_ascii=False).encode("utf-8"),
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json",
            },
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=timeout) as response:
                payload = json.loads(response.read().decode("utf-8"))
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="ignore")
            last_error = RuntimeError(f"DeepSeek API HTTP {exc.code}: {detail}")
            if exc.code in {408, 409, 425, 429, 500, 502, 503, 504} and attempt < retries:
                time.sleep(min(3.0 * (attempt + 1), 15.0))
                continue
            raise last_error from exc
        except urllib.error.URLError as exc:
            last_error = RuntimeError(f"DeepSeek API connection failed: {exc}")
            if attempt < retries:
                time.sleep(min(3.0 * (attempt + 1), 15.0))
                continue
            raise last_error from exc
        except http.client.IncompleteRead as exc:
            last_error = RuntimeError(f"DeepSeek API response was interrupted: {exc}")
            if attempt < retries:
                time.sleep(min(3.0 * (attempt + 1), 15.0))
                continue
            raise last_error from exc
        except TimeoutError as exc:
            last_error = RuntimeError(f"DeepSeek API request timed out: {exc}")
            if attempt < retries:
                time.sleep(min(3.0 * (attempt + 1), 15.0))
                continue
            raise last_error from exc

        content = payload["choices"][0]["message"]["content"]
        try:
            result = parse_deepseek_json_content(content)
            break
        except RuntimeError as exc:
            last_error = exc
            if attempt < retries:
                time.sleep(min(2.0 * (attempt + 1), 6.0))
                continue
            raise
    else:
        raise RuntimeError(f"DeepSeek JSON parsing failed: {last_error}") from last_error

    result["status"] = "generated"
    result["model"] = model
    result["generated_at"] = int(time.time())
    return result


def normalize_deepseek_topic_result(result: dict, topic: int, topic_size: int, is_outlier: bool, cache_key: str) -> dict:
    route_name_cn = normalize_space(safe_text(result.get("route_name_cn", "")))
    route_name_en = normalize_space(safe_text(result.get("route_name_en", "")))
    topic_summary = normalize_space(safe_text(result.get("topic_summary", "")))
    topic_description = normalize_space(safe_text(result.get("topic_description", "")))
    route_sentences = string_list(result.get("technology_route_sentences", []))
    evidence_sentences = string_list(result.get("evidence_sentences", []))
    fusion_industry_chain_position = normalize_space(
        safe_text(result.get("fusion_industry_chain_position", ""))
    )
    fusion_industry_chain_relation = normalize_space(
        safe_text(result.get("fusion_industry_chain_relation", ""))
    )
    fusion_application_scenarios = string_list(result.get("fusion_application_scenarios", []))
    if not fusion_industry_chain_position:
        fusion_industry_chain_position = "关系尚不明确"
    if not fusion_industry_chain_relation:
        fusion_industry_chain_relation = "代表专利证据不足，暂不能确定该技术与核聚变产业链的具体关系。"
    if not fusion_application_scenarios:
        fusion_application_scenarios = ["代表专利证据不足，具体核聚变应用场景仍需进一步验证。"]
    is_fusion_related, fusion_relevance, fusion_relevance_reason = normalize_fusion_relevance(result)

    if not topic_summary:
        if topic_description:
            topic_summary = topic_description.split("。", 1)[0].strip() + "。"
        elif route_sentences:
            topic_summary = route_sentences[0]
        else:
            topic_summary = "该主题需要结合代表专利进一步人工复核。"

    return {
        "topic_id": int(topic),
        "topic_size": int(topic_size),
        "is_bertopic_outlier": bool(is_outlier),
        "topic_keywords": topic_summary,
        "route_name_cn": route_name_cn,
        "route_name_en": route_name_en,
        "topic_summary": topic_summary,
        "topic_description": topic_description,
        "technology_route_sentences": " || ".join(route_sentences),
        "evidence_sentences": " || ".join(evidence_sentences),
        "fusion_industry_chain_position": fusion_industry_chain_position,
        "fusion_industry_chain_relation": fusion_industry_chain_relation,
        "fusion_application_scenarios": " || ".join(fusion_application_scenarios),
        "is_fusion_related": bool(is_fusion_related),
        "fusion_relevance": fusion_relevance,
        "fusion_relevance_reason": fusion_relevance_reason,
        "confidence": normalize_space(safe_text(result.get("confidence", "unknown"))) or "unknown",
        "deepseek_status": normalize_space(safe_text(result.get("status", "unknown"))),
        "deepseek_model": normalize_space(safe_text(result.get("model", ""))),
        "deepseek_cache_key": cache_key,
    }


def compute_deepseek_topic_sentences(
    docs: pd.DataFrame,
    embeddings: np.ndarray,
    topic_index: pd.DataFrame,
    topic_embeddings: np.ndarray,
    args: argparse.Namespace,
) -> pd.DataFrame:
    require_sklearn()
    topic_ids = docs["topic_id"].astype(int).to_numpy()
    doc_embeddings = normalize(np.asarray(embeddings, dtype=np.float64), norm="l2", axis=1)
    cache_path = data_path(args.deepseek_topic_cache)
    cache = load_deepseek_topic_cache(cache_path)
    api_key = os.environ.get(args.deepseek_api_key_env, "").strip()
    rows_by_topic: dict[int, dict] = {}
    pending = []
    ordered_topics = topic_index["topic_id"].astype(int).to_numpy().tolist()

    for pos, topic_value in enumerate(topic_index["topic_id"].astype(int).to_numpy()):
        topic = int(topic_value)
        topic_doc_indices = np.where(topic_ids == topic)[0]
        topic_size = int(len(topic_doc_indices))
        cache_key = f"topic_{topic}_outlier" if topic == -1 else ""

        if topic == -1:
            result = outlier_topic_interpretation()
            rows_by_topic[topic] = normalize_deepseek_topic_result(result, topic, topic_size, True, cache_key)
            continue

        similarities = doc_embeddings[topic_doc_indices] @ topic_embeddings[pos]
        representative_count = min(max(1, int(args.deepseek_topic_docs)), topic_size)
        representative_indices = topic_doc_indices[np.argsort(-similarities)[:representative_count]]
        topic_payload = build_topic_evidence_payload(
            docs=docs,
            topic=topic,
            topic_doc_indices=topic_doc_indices,
            representative_indices=representative_indices,
        )
        signature = deepseek_payload_signature(
            {
                "model": args.deepseek_model,
                "topic": topic_payload,
            }
        )
        cache_key = f"topic_{topic}_{signature}"
        cached = cache.get(cache_key)
        if cached and not args.refresh_deepseek_topics and cached.get("status") in {"generated", "generated_local"}:
            print(f"Topic {topic}: using cached summary.")
            rows_by_topic[topic] = normalize_deepseek_topic_result(cached, topic, topic_size, False, cache_key)
        elif args.local_topic_summaries:
            result = local_topic_interpretation(topic_payload)
            cache[cache_key] = result
            rows_by_topic[topic] = normalize_deepseek_topic_result(result, topic, topic_size, False, cache_key)
            save_deepseek_topic_cache(cache_path, cache)
            print(f"Topic {topic}: generated locally from IncoPat labels.")
        else:
            if not api_key:
                raise RuntimeError(
                    f"DeepSeek topic extraction is required, but environment variable "
                    f"{args.deepseek_api_key_env} is not set and no valid cache exists for topic {topic}. "
                    f"Set {args.deepseek_api_key_env} or provide {cache_path}."
                )
            prompt = build_deepseek_topic_prompt(topic_payload)
            pending.append({
                "topic": topic,
                "topic_size": topic_size,
                "cache_key": cache_key,
                "representative_count": representative_count,
                "prompt": build_deepseek_topic_prompt(topic_payload),
            })

    def generate(task: dict) -> tuple[dict, dict]:
        topic = task["topic"]
        print(
            f"DeepSeek topic {topic}: generating summary from "
            f"{task['representative_count']} representative docs..."
        )
        result = call_deepseek_topic_sentence(
            prompt=task["prompt"],
            api_key=api_key,
            model=args.deepseek_model,
            base_url=args.deepseek_base_url,
            timeout=int(args.deepseek_timeout),
            retries=int(args.deepseek_retries),
        )
        return task, result

    failures = []
    if pending:
        workers = max(1, min(int(args.deepseek_workers), len(pending)))
        print(f"DeepSeek topic generation: {len(pending)} pending, {workers} workers.")
        with ThreadPoolExecutor(max_workers=workers) as executor:
            future_tasks = {executor.submit(generate, task): task for task in pending}
            for future in as_completed(future_tasks):
                task = future_tasks[future]
                topic = task["topic"]
                cache_key = task["cache_key"]
                try:
                    _, result = future.result()
                except Exception as exc:
                    cache[cache_key] = {
                        "status": "failed",
                        "error": str(exc),
                        "model": args.deepseek_model,
                        "generated_at": int(time.time()),
                    }
                    failures.append((topic, exc))
                else:
                    cache[cache_key] = result
                    rows_by_topic[topic] = normalize_deepseek_topic_result(
                        result, topic, task["topic_size"], False, cache_key
                    )
                    print(f"DeepSeek topic {topic}: completed.")
                save_deepseek_topic_cache(cache_path, cache)

    if failures:
        topics = ", ".join(str(topic) for topic, _ in failures[:12])
        raise RuntimeError(f"DeepSeek topic extraction failed for {len(failures)} topics: {topics}") from failures[0][1]

    rows = [rows_by_topic[int(topic)] for topic in ordered_topics]
    save_deepseek_topic_cache(cache_path, cache)
    return pd.DataFrame(rows)


def relabel_non_fusion_topics_as_noise(docs: pd.DataFrame, topic_keywords: pd.DataFrame) -> dict[str, int]:
    docs["is_deepseek_non_fusion_noise"] = False
    docs["deepseek_fusion_relevance"] = ""
    docs["deepseek_fusion_relevance_reason"] = ""
    docs["topic_id_before_deepseek_filter"] = docs["topic_id"].astype(int)
    docs["deepseek_non_fusion_topic_id"] = ""

    if topic_keywords.empty or "topic_id" not in topic_keywords.columns:
        stats = {
            "deepseek_non_fusion_topic_count": 0,
            "deepseek_non_fusion_doc_count": 0,
            "topic_count_excluding_minus_1_after_deepseek_filter": int(docs.loc[docs["topic_id"].ne(-1), "topic_id"].nunique()),
            "topic_count_including_minus_1_after_deepseek_filter": int(docs["topic_id"].nunique()),
            "noise_doc_count_after_deepseek_filter": int(docs["topic_id"].eq(-1).sum()),
        }
        docs.attrs["deepseek_relevance_filter_stats"] = stats
        return stats

    relevance_map = {
        int(row["topic_id"]): normalize_space(safe_text(row.get("fusion_relevance", "")))
        for _, row in topic_keywords.iterrows()
        if pd.notna(row.get("topic_id", np.nan))
    }
    reason_map = {
        int(row["topic_id"]): normalize_space(safe_text(row.get("fusion_relevance_reason", "")))
        for _, row in topic_keywords.iterrows()
        if pd.notna(row.get("topic_id", np.nan))
    }
    related_map = {
        int(row["topic_id"]): deepseek_bool(row.get("is_fusion_related", True), default=True)
        for _, row in topic_keywords.iterrows()
        if pd.notna(row.get("topic_id", np.nan))
    }

    docs["deepseek_fusion_relevance"] = docs["topic_id"].astype(int).map(relevance_map).fillna("")
    docs["deepseek_fusion_relevance_reason"] = docs["topic_id"].astype(int).map(reason_map).fillna("")

    non_fusion_topics = sorted(
        topic
        for topic, is_related in related_map.items()
        if topic != -1 and not is_related
    )
    non_fusion_mask = docs["topic_id"].isin(non_fusion_topics)
    docs["is_deepseek_non_fusion_noise"] = non_fusion_mask
    if non_fusion_topics:
        docs.loc[non_fusion_mask, "deepseek_non_fusion_topic_id"] = docs.loc[non_fusion_mask, "topic_id"].astype(int).astype(str)
        docs.loc[non_fusion_mask, "topic_id"] = -1
        docs.loc[non_fusion_mask, "topic_probability"] = 0.0
        docs["is_bertopic_outlier"] = docs["topic_id"].eq(-1)

    stats = {
        "deepseek_non_fusion_topic_count": int(len(non_fusion_topics)),
        "deepseek_non_fusion_doc_count": int(non_fusion_mask.sum()),
        "topic_count_excluding_minus_1_after_deepseek_filter": int(docs.loc[docs["topic_id"].ne(-1), "topic_id"].nunique()),
        "topic_count_including_minus_1_after_deepseek_filter": int(docs["topic_id"].nunique()),
        "noise_doc_count_after_deepseek_filter": int(docs["topic_id"].eq(-1).sum()),
    }
    docs.attrs["deepseek_relevance_filter_stats"] = stats
    return stats


def fit_trend_for_topic(
    topic: int,
    year_counts: pd.DataFrame,
    fitting_years: np.ndarray,
    min_points: int,
) -> tuple[float, float, float, str]:
    subset = year_counts[
        (year_counts["topic_id"] == topic) & (year_counts["year"].isin(fitting_years))
    ].sort_values("year")
    subset = subset[subset["total_year_count"] > 0].copy()
    if len(subset) < min_points:
        return (np.nan, np.nan, np.nan, "insufficient_year_points")

    y = subset["topic_year_count"].astype(float).to_numpy()
    total = subset["total_year_count"].astype(float).to_numpy()
    x = subset["year"].astype(float).to_numpy()
    x_scaled = x - np.min(x)

    try:
        import statsmodels.api as sm

        design = sm.add_constant(x_scaled, has_constant="add")
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            model = sm.GLM(
                y,
                design,
                family=sm.families.NegativeBinomial(),
                offset=np.log(total),
            )
            result = model.fit(maxiter=200, disp=0)
        beta = float(result.params[1])
        if np.isfinite(beta):
            growth = float(math.exp(beta) - 1.0)
            return (growth, beta, growth, "negative_binomial_glm")
    except Exception:
        pass

    share = (y + 0.5) / (total + 1.0)
    if len(np.unique(x_scaled)) < 2:
        return (np.nan, np.nan, np.nan, "fallback_failed")
    slope = float(np.polyfit(x_scaled, np.log(share), 1)[0])
    growth = float(math.exp(slope) - 1.0)
    return (growth, slope, growth, "fallback_log_share_slope")


def build_year_counts(docs: pd.DataFrame) -> pd.DataFrame:
    valid = docs.dropna(subset=["year", "topic_id"]).copy()
    if valid.empty:
        return pd.DataFrame(
            columns=["topic_id", "year", "topic_year_count", "total_year_count", "topic_year_share"]
        )
    valid["year"] = valid["year"].astype(int)
    years = np.arange(valid["year"].min(), valid["year"].max() + 1, dtype=int)
    topics = np.array(sorted(valid["topic_id"].astype(int).unique()), dtype=int)
    total_counts = valid.groupby("year").size().reindex(years, fill_value=0)
    topic_counts = valid.groupby(["topic_id", "year"]).size()

    rows = []
    for topic in topics:
        for year in years:
            topic_count = int(topic_counts.get((topic, year), 0))
            total_count = int(total_counts.loc[year])
            rows.append(
                {
                    "topic_id": int(topic),
                    "year": int(year),
                    "topic_year_count": topic_count,
                    "total_year_count": total_count,
                    "topic_year_share": topic_count / total_count if total_count else np.nan,
                }
            )
    return pd.DataFrame(rows)


def compute_indicator_tables(
    docs: pd.DataFrame,
    embeddings: np.ndarray,
    recent_window: int,
    min_year_points: int,
    args: argparse.Namespace,
) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    topic_index, topic_embeddings = compute_topic_embeddings(embeddings, docs["topic_id"].astype(int).to_numpy())
    topic_keywords = compute_deepseek_topic_sentences(docs, embeddings, topic_index, topic_embeddings, args)
    relevance_stats = (
        keep_all_topics_in_scope(docs)
        if args.all_topics_related
        else relabel_non_fusion_topics_as_noise(docs, topic_keywords)
    )
    if relevance_stats["deepseek_non_fusion_topic_count"]:
        print(
            "Relabelled DeepSeek non-fusion topics as noise: "
            f"{relevance_stats['deepseek_non_fusion_topic_count']} topics, "
            f"{relevance_stats['deepseek_non_fusion_doc_count']} patent families."
        )
        topic_index, topic_embeddings = compute_topic_embeddings(embeddings, docs["topic_id"].astype(int).to_numpy())
        topic_keywords = compute_deepseek_topic_sentences(docs, embeddings, topic_index, topic_embeddings, args)
    representatives = compute_representative_docs(docs, embeddings, topic_index, topic_embeddings)
    topic_keywords["representative_docs"] = topic_keywords["topic_id"].map(representatives).fillna("")

    raw = topic_keywords.copy()
    citation = docs.groupby("topic_id")["citation_count"]
    raw = raw.merge(
        citation.mean().rename("impact_mean_citation_raw").reset_index(),
        on="topic_id",
        how="left",
    )
    log_citation = docs.assign(_log_citation=np.log1p(pd.to_numeric(docs["citation_count"], errors="coerce")))
    raw = raw.merge(
        log_citation.groupby("topic_id")["_log_citation"]
        .mean()
        .rename("impact_log_mean_citation_raw")
        .reset_index(),
        on="topic_id",
        how="left",
    )
    raw["impact_raw"] = raw["impact_log_mean_citation_raw"]

    years = docs.groupby("topic_id")["year"].agg(["mean", "median", "min", "max"]).reset_index()
    years.columns = ["topic_id", "year_mean", "year_median", "year_min", "year_max"]
    raw = raw.merge(years, on="topic_id", how="left")
    raw["novelty_raw"] = raw["year_mean"]

    year_counts = build_year_counts(docs)
    if not year_counts.empty:
        observed_years = (
            year_counts.loc[year_counts["total_year_count"] > 0, "year"]
            .drop_duplicates()
            .sort_values()
            .to_numpy(dtype=int)
        )
    else:
        observed_years = np.array([], dtype=int)

    trend_rows = []
    for topic in raw["topic_id"].astype(int):
        if len(observed_years) == 0:
            short = (np.nan, np.nan, np.nan, "missing_year")
            long = (np.nan, np.nan, np.nan, "missing_year")
        else:
            recent_start = int(observed_years.max() - recent_window + 1)
            short_years = observed_years[observed_years >= recent_start]
            short = fit_trend_for_topic(topic, year_counts, short_years, min_year_points)
            long = fit_trend_for_topic(topic, year_counts, observed_years, min_year_points)
        trend_rows.append(
            {
                "topic_id": topic,
                "short_trend_raw": short[0],
                "short_trend_beta_raw": short[1],
                "short_trend_growth_raw": short[2],
                "short_trend_method": short[3],
                "long_trend_raw": long[0],
                "long_trend_beta_raw": long[1],
                "long_trend_growth_raw": long[2],
                "long_trend_method": long[3],
            }
        )
    raw = raw.merge(pd.DataFrame(trend_rows), on="topic_id", how="left")

    if len(topic_embeddings) >= 2:
        similarity = topic_embeddings @ topic_embeddings.T
        centrality = (similarity.sum(axis=1) - 1.0) / (len(topic_embeddings) - 1)
    else:
        centrality = np.full(len(topic_embeddings), np.nan)
    centrality_df = topic_index.copy()
    centrality_df["centrality_raw"] = centrality
    raw = raw.merge(centrality_df, on="topic_id", how="left")

    cross_domain = compute_cross_domain(docs)
    raw = raw.merge(cross_domain, on="topic_id", how="left")

    lof_df = topic_index.copy()
    if len(topic_embeddings) >= 3:
        k = min(10, len(topic_embeddings) - 1)
        lof = LocalOutlierFactor(n_neighbors=k, metric="cosine")
        lof.fit_predict(topic_embeddings)
        lof_df["lof_raw"] = -lof.negative_outlier_factor_
    else:
        lof_df["lof_raw"] = np.nan
    raw = raw.merge(lof_df, on="topic_id", how="left")

    raw = raw[
        [
            "topic_id",
            "topic_size",
            "is_bertopic_outlier",
            "topic_keywords",
            "route_name_cn",
            "route_name_en",
            "topic_summary",
            "topic_description",
            "technology_route_sentences",
            "evidence_sentences",
            "fusion_industry_chain_position",
            "fusion_industry_chain_relation",
            "fusion_application_scenarios",
            "is_fusion_related",
            "fusion_relevance",
            "fusion_relevance_reason",
            "confidence",
            "deepseek_status",
            "deepseek_model",
            "deepseek_cache_key",
            "representative_docs",
            "impact_raw",
            "impact_mean_citation_raw",
            "impact_log_mean_citation_raw",
            "novelty_raw",
            "year_mean",
            "year_median",
            "year_min",
            "year_max",
            "short_trend_raw",
            "short_trend_beta_raw",
            "short_trend_growth_raw",
            "short_trend_method",
            "long_trend_raw",
            "long_trend_beta_raw",
            "long_trend_growth_raw",
            "long_trend_method",
            "centrality_raw",
            "cross_domain_raw",
            "ipc_entropy_raw",
            "ipc_subclass_count",
            "ipc_subclasses",
            "lof_raw",
        ]
    ].sort_values("topic_id")

    normalized = normalize_indicator_table(raw)
    topic_embedding_df = pd.DataFrame(topic_embeddings, columns=[f"emb_{i:03d}" for i in range(topic_embeddings.shape[1])])
    topic_embedding_df.insert(0, "topic_id", topic_index["topic_id"].astype(int).to_numpy())
    return raw, normalized, year_counts, topic_embedding_df


def keep_all_topics_in_scope(docs: pd.DataFrame) -> dict[str, int]:
    """Retain all IncoPat families under the confirmed all-related rule."""
    docs["is_deepseek_non_fusion_noise"] = False
    docs["deepseek_fusion_relevance"] = ""
    docs["deepseek_fusion_relevance_reason"] = ""
    docs["topic_id_before_deepseek_filter"] = docs["topic_id"].astype(int)
    docs["deepseek_non_fusion_topic_id"] = ""
    stats = {
        "deepseek_non_fusion_topic_count": 0,
        "deepseek_non_fusion_doc_count": 0,
        "topic_count_excluding_minus_1_after_deepseek_filter": int(docs.loc[docs["topic_id"].ne(-1), "topic_id"].nunique()),
        "topic_count_including_minus_1_after_deepseek_filter": int(docs["topic_id"].nunique()),
        "noise_doc_count_after_deepseek_filter": int(docs["topic_id"].eq(-1).sum()),
    }
    docs.attrs["deepseek_relevance_filter_stats"] = stats
    return stats


def compute_cross_domain(docs: pd.DataFrame) -> pd.DataFrame:
    all_codes = [code for codes in docs["_ipc_list"] for code in codes]
    global_codes = sorted(set(all_codes))
    global_denominator = math.log(len(global_codes)) if len(global_codes) > 1 else np.nan

    rows = []
    for topic, group in docs.groupby("topic_id", sort=True):
        counter: Counter[str] = Counter()
        for codes in group["_ipc_list"]:
            counter.update(codes)
        total = sum(counter.values())
        if total == 0 or not np.isfinite(global_denominator):
            entropy = np.nan
            diversity = np.nan
        else:
            probs = np.asarray([count / total for count in counter.values()], dtype=float)
            entropy = float(-(probs * np.log(probs)).sum())
            diversity = float(entropy / global_denominator)
        rows.append(
            {
                "topic_id": int(topic),
                "cross_domain_raw": diversity,
                "ipc_entropy_raw": entropy,
                "ipc_subclass_count": int(len(counter)),
                "ipc_subclasses": "; ".join(code for code, _ in counter.most_common()),
            }
        )
    return pd.DataFrame(rows)


def percentile_score(values: pd.Series, winsorize: bool = True) -> pd.Series:
    raw = pd.to_numeric(values, errors="coerce")
    out = pd.Series(np.nan, index=values.index, dtype=float)
    valid = raw.dropna()
    if valid.empty:
        return out
    working = valid.copy()
    if winsorize and len(working) > 2:
        lower = working.quantile(0.01)
        upper = working.quantile(0.99)
        working = working.clip(lower=lower, upper=upper)
    if working.nunique(dropna=True) == 1:
        out.loc[working.index] = 0.5
        return out
    ranks = working.rank(method="average", ascending=True)
    out.loc[working.index] = (ranks - 1.0) / (len(working) - 1.0)
    return out


def normalize_indicator_table(raw: pd.DataFrame) -> pd.DataFrame:
    mapping = {
        "impact_raw": "impact_score",
        "novelty_raw": "novelty_score",
        "short_trend_raw": "short_trend_score",
        "long_trend_raw": "long_trend_score",
        "centrality_raw": "centrality_score",
        "cross_domain_raw": "cross_domain_score",
        "lof_raw": "lof_score",
    }
    normalized = raw[["topic_id", "topic_size", "is_bertopic_outlier", "topic_keywords"]].copy()
    for col in [
        "route_name_cn",
        "route_name_en",
        "topic_summary",
        "topic_description",
        "technology_route_sentences",
        "evidence_sentences",
        "fusion_industry_chain_position",
        "fusion_industry_chain_relation",
        "fusion_application_scenarios",
        "is_fusion_related",
        "fusion_relevance",
        "fusion_relevance_reason",
        "confidence",
        "deepseek_status",
        "deepseek_model",
        "deepseek_cache_key",
    ]:
        if col in raw.columns:
            normalized[col] = raw[col]
    for raw_col, score_col in mapping.items():
        normalized[score_col] = percentile_score(raw[raw_col], winsorize=True)
    return normalized


def output_path_for_new_file(path: Path) -> Path:
    if not path.exists():
        return path
    stem = path.stem
    suffix = path.suffix
    parent = path.parent
    index = 2
    while True:
        candidate = parent / f"{stem}_{index}{suffix}"
        if not candidate.exists():
            return candidate
        index += 1


def write_workbook(
    output_path: Path,
    docs: pd.DataFrame,
    topic_keywords: pd.DataFrame,
    year_counts: pd.DataFrame,
    raw: pd.DataFrame,
    normalized: pd.DataFrame,
    topic_embeddings: pd.DataFrame,
    run_log: pd.DataFrame,
) -> None:
    preprocessed_cols = [
        "doc_id",
        "source_family_id",
        "source_representative_lens_id",
        "source_lens_id",
        "source_display_key",
        "source_jurisdiction",
        "source_document_type",
        "source_legal_status",
        "source_publication_date",
        "TI_raw",
        "TI_clean",
        "TI_norm",
        "TI_embed_text",
        "AB_raw",
        "AB_clean",
        "AB_norm",
        "AB_embed_text",
        "patentbert_text",
        "TI_repr_text",
        "year",
        "citation_count",
        "ipc_raw",
        "ipc_subclasses",
    ]
    doc_topic_cols = [
        "doc_id",
        "source_family_id",
        "source_representative_lens_id",
        "source_lens_id",
        "source_display_key",
        "source_jurisdiction",
        "source_document_type",
        "source_legal_status",
        "source_publication_date",
        "topic_id",
        "topic_id_raw",
        "topic_id_before_deepseek_filter",
        "is_bertopic_outlier",
        "is_small_topic_noise",
        "is_deepseek_non_fusion_noise",
        "deepseek_non_fusion_topic_id",
        "deepseek_fusion_relevance",
        "deepseek_fusion_relevance_reason",
        "raw_topic_size",
        "TI_raw",
        "TI_embed_text",
        "AB_raw",
        "AB_embed_text",
        "patentbert_text",
        "TI_repr_text",
        "year",
        "citation_count",
        "ipc_raw",
        "ipc_subclasses",
        "topic_probability",
    ]
    preprocessed = docs[[col for col in preprocessed_cols if col in docs.columns]].copy()
    doc_topics = docs[[col for col in doc_topic_cols if col in docs.columns]].copy()

    with pd.ExcelWriter(output_path, engine="openpyxl") as writer:
        preprocessed.to_excel(writer, sheet_name="01_preprocessed_docs", index=False)
        doc_topics.to_excel(writer, sheet_name="02_doc_topics", index=False)
        topic_keywords.to_excel(writer, sheet_name="03_topic_keywords", index=False)
