        raw.to_excel(writer, sheet_name="05_indicator_raw", index=False)
        normalized.to_excel(writer, sheet_name="06_indicator_norm", index=False)
        topic_embeddings.to_excel(writer, sheet_name="topic_embeddings", index=False)
        run_log.to_excel(writer, sheet_name="run_log", index=False)


